ST.xhtml:p:
Rtring_Q(CLK :=SaveFlag);
IF Rtring_Q.Q THEN
  g_SaveAllMControlExecute[Index].MCode :=INT_TO_LREAL(MCode);
  g_SaveAllMControlExecute[Index].MP := MP;
  g_SaveAllMControlExecute[Index].MQ := MQ;
  g_SaveAllMControlExecute[Index].MI := MI;
  g_SaveAllMControlExecute[Index].MJ := MJ;
  g_SaveAllMControlExecute[Index].MK := MK;
  g_SaveAllMControlExecute[Index].MH := MH;
  g_SaveAllMControlExecute[Index].MTime := LogTime;

	IF Index >= 9 THEN
		FOR number :=0 TO 9 BY 1 DO
			g_PreSaveAllMControlExecute[number].MCode := g_SaveAllMControlExecute[number].MCode;
		    g_PreSaveAllMControlExecute[number].MP :=g_SaveAllMControlExecute[number].MP;
		    g_PreSaveAllMControlExecute[number].MQ := g_SaveAllMControlExecute[number].MQ;
		    g_PreSaveAllMControlExecute[number].MI := g_SaveAllMControlExecute[number].MI;
		    g_PreSaveAllMControlExecute[number].MJ := g_SaveAllMControlExecute[number].MJ;
		    g_PreSaveAllMControlExecute[number].MK := g_SaveAllMControlExecute[number].MK;
		    g_PreSaveAllMControlExecute[number].MH :=  g_SaveAllMControlExecute[number].MH;
            g_PreSaveAllMControlExecute[number].MTime := g_SaveAllMControlExecute[number].MTime;
            (*清空*)
            g_SaveAllMControlExecute[number].MCode := 0.0;
		    g_SaveAllMControlExecute[number].MP :=0.0;
		    g_SaveAllMControlExecute[number].MQ :=0.0;
		    g_SaveAllMControlExecute[number].MI := 0.0;
		    g_SaveAllMControlExecute[number].MJ := 0.0;
		    g_SaveAllMControlExecute[number].MH :=  0.0;
             g_SaveAllMControlExecute[number].MTime := 0;
        END_FOR;
		g_bNotifyHMIToAcquireValue := TRUE;
	END_IF;
END_IF;
